import { test, expect } from '@playwright/test';

test.describe('401 Error Handling - Redirect to Login', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should redirect to login when API returns 401 Unauthorized', async ({ page }) => {
    // Intercept the protected API endpoint
    await page.route('/api/user/profile', (route) => {
      route.abort('failed');
      route.continue();
    });

    // Mock the 401 response
    await page.route('/api/user/profile', (route) => {
      route.fulfill({
        status: 401,
        body: JSON.stringify({ error: 'Unauthorized' }),
      });
    });

    // Verify user is on dashboard before API call
    const dashboardHeader = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardHeader).toBeVisible();

    // Trigger the API call by clicking a protected button
    const profileButton = page.getByRole('button', { name: /profile/i });
    await profileButton.click();

    // Wait for navigation to complete
    await page.waitForURL(/\/login/);

    // Verify user is redirected to login page
    const loginHeader = page.getByRole('heading', { name: /login/i });
    await expect(loginHeader).toBeVisible();

    // Verify login form is visible
    const emailInput = page.getByLabel(/email/i);
    await expect(emailInput).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/unauthorized/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should handle multiple 401 errors and redirect to login', async ({ page }) => {
    // Intercept the first API call and return 401
    await page.route('/api/user/settings', (route) => {
      route.fulfill({
        status: 401,
        body: JSON.stringify({ error: 'Unauthorized' }),
      });
    });

    // Trigger the first API call
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await settingsButton.click();

    // Verify redirect to login
    await page.waitForURL(/\/login/);
    const loginHeader = page.getByRole('heading', { name: /login/i });
    await expect(loginHeader).toBeVisible();

    // Verify login form is visible
    const passwordInput = page.getByLabel(/password/i);
    await expect(passwordInput).toBeVisible();

    // Verify user is not on dashboard
    const dashboardHeader = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardHeader).not.toBeVisible();

    // Verify redirect persists if user tries to navigate back
    await page.goBack();
    await page.waitForURL(/\/login/);
    await expect(loginHeader).toBeVisible();
  });
});
